<?php declare(strict_types=1); echo $view->render('components.page-hero',compact('page','e')); $full=$event['capacity']!==null&&(int)$event['registration_count']>=(int)$event['capacity'];$closed=$event['registration_deadline']!==null&&strtotime($event['registration_deadline'])<time(); ?>
<section class="section"><div class="container-narrow"><?php if($message):?><div class="notice" role="status"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="form-error" role="alert"><?= $e($error) ?></div><?php endif;?><dl class="detail-list"><div><dt>Date</dt><dd><?= $e($event['event_date']) ?></dd></div><div><dt>Time</dt><dd><?= $e($event['start_time']?:'To be announced') ?><?= $event['end_time']?' – '.$e($event['end_time']):'' ?></dd></div><div><dt>Venue</dt><dd><?= $e($event['venue']?:'Online / to be announced') ?></dd></div><div><dt>Fee</dt><dd><?= $event['fee']===null?'Not specified':$e($event['fee_currency'].' '.number_format((float)$event['fee'],2)) ?></dd></div><div><dt>Eligibility</dt><dd><?= $e($event['eligibility']?:'See registration access requirements.') ?></dd></div></dl>
<?php if($event['online_url']):?><p><a class="text-link" href="<?= $e($event['online_url']) ?>" rel="noopener noreferrer">Online event information</a></p><?php endif;?>
<?php if($full||$closed):?><div class="notice" role="status">Registration is closed.</div><?php elseif($event['registration_access']==='member'):?><p><a class="btn btn-navy" href="/account/event-registrations?event=<?= rawurlencode($event['public_id']) ?>&amp;event_slug=<?= rawurlencode($event['slug']) ?>">Sign in as a member to register</a></p><?php else:?><form method="post" action="/events/<?= rawurlencode($event['public_id']) ?>/register" class="form-grid"><?= $csrf->field() ?><input type="hidden" name="event_slug" value="<?= $e($event['slug']) ?>"><label>Name<input name="name" maxlength="200" required></label><label>Email<input type="email" name="email" maxlength="254" required></label><label>Phone<input name="phone" maxlength="40"></label><button class="btn btn-navy" type="submit">Register for event</button></form><?php endif;?></div></section>
